def main():
    with tempfile.TemporaryDirectory(prefix='spbu-free-rooms-') as directory:
        root = Path(directory)
        with zipfile.ZipFile(io.BytesIO(base64.b85decode(''.join(PAYLOAD)))) as archive:
            # Имена ресурсов задаются при сборке этого файла.
            archive.extractall(root)
        sys.path.insert(0, str(root))
        try:
            runpy.run_path(str(root / 'app.py'), run_name='__main__')
        finally:
            sys.path.remove(str(root))

if __name__ == '__main__':
    main()
